+int main(int argc, char *argv[]) {
+  @autoreleasepool {
+    NSString *realmPath = @"/Users/radoniusz/Library/Developer/CoreSimulator/Devices/53CBD69C-E05C-4DAC-9A2C-2504C42CB57F/data/Containers/Data/Application/B4834A56-4709-4E8D-9ED9-30026F3818A1/Library/Caches/@alice:localhost/Aggregations/Aggregations.realm";
+
+    Class configClass = NSClassFromString(@"RLMRealmConfiguration");
+    Class realmClass = NSClassFromString(@"RLMRealm");
+    if (!configClass || !realmClass) {
+      printf("Realm classes missing\n");
+      return 1;
+    }
+
+    id config = MsgSendId(configClass, @selector(defaultConfiguration));
+    [config setValue:[NSURL fileURLWithPath:realmPath] forKey:@"fileURL"];
+
+    NSError *error = nil;
