import plistlib, pathlib
from plistlib import UID

path = pathlib.Path('/Users/radoniusz/Library/Developer/CoreSimulator/Devices/53CBD69C-E05C-4DAC-9A2C-2504C42CB57F/data/Containers/Shared/AppGroup/58B41E47-2302-430E-B165-30206FF0042C/MXFileStore/@alice:localhost/rooms/!iXzQwfCBtArPYzbVbw:localhost/messages')
archive = plistlib.load(path.open('rb'))
objects = archive['$objects']

cache = {}

def resolve(obj):
    if isinstance(obj, UID):
        idx = obj.data
        if idx in cache:
            return cache[idx]
        val = objects[idx]
        cache[idx] = None
        res = resolve(val)
        cache[idx] = res
        return res
    if isinstance(obj, dict):
        if '$class' in obj:
            cls = resolve(obj['$class'])
            # keyed archive classes are encoded as dicts with $classname
            if isinstance(cls, dict) and '$classname' in cls:
                clsname = cls['$classname']
            else:
                clsname = None
            if clsname in ('NSArray', 'NSMutableArray'):
                return [resolve(v) for k, v in obj.items() if k == 'NS.objects'][0]
            if clsname in ('NSDictionary', 'NSMutableDictionary'):
                keys = [resolve(v) for v in obj['NS.keys']]
                vals = [resolve(v) for v in obj['NS.objects']]
                return dict(zip(keys, vals))
            if clsname == 'NSString':
                return obj.get('NS.string', '')
            if clsname in ('NSNumber', 'NSDecimalNumber'):
                return obj.get('NS.value')
            if clsname == 'NSData':
                return obj.get('NS.data')
            # fallback: resolve entries except class
            return {k: resolve(v) for k, v in obj.items() if k != '$class'}
        return {k: resolve(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [resolve(v) for v in obj]
    return obj

root = resolve(archive['$top']['root'])
msgs = resolve(root['messages'])
print('messages count', len(msgs))
for i, ev in enumerate(msgs, 1):
    et = ev.get('eventType')
    sender = ev.get('userId')
    content = resolve(ev.get('content')) if isinstance(ev.get('content'), (dict, UID, list)) else ev.get('content')
    body = None
    if isinstance(content, dict):
        body = content.get('body') or content.get('name') or content.get('topic')
    print(f'{i}. type={et} sender={sender} body={body!r}')
